"""Command line interface for pennywise."""

import argparse
import csv
import io
import json
import re
import sys
from datetime import date

from . import ledger
from .ledger import ParseError


def _date_arg(value):
    if re.fullmatch(r"\d{4}-\d{2}-\d{2}", value, re.ASCII):
        try:
            return date(int(value[:4]), int(value[5:7]), int(value[8:10]))
        except ValueError:
            pass
    raise argparse.ArgumentTypeError(
        "invalid date %r (expected a real date as YYYY-MM-DD)" % value
    )


def _build_parser():
    p = argparse.ArgumentParser(
        prog="pennywise", description="Read a plain-text household ledger."
    )
    sub = p.add_subparsers(dest="command", metavar="COMMAND")

    s = sub.add_parser("balance", help="print the total balance")
    s.add_argument("file", metavar="FILE")
    s.add_argument("--json", action="store_true", help="print JSON")

    s = sub.add_parser("summary", help="totals per category or month")
    s.add_argument("file", metavar="FILE")
    s.add_argument("--by", choices=["category", "month"], default="category")
    s.add_argument("--json", action="store_true", help="print JSON")

    s = sub.add_parser("list", help="list entries, oldest first")
    s.add_argument("file", metavar="FILE")
    s.add_argument("--category")
    s.add_argument("--since", type=_date_arg)
    s.add_argument("--until", type=_date_arg)
    s.add_argument("--json", action="store_true", help="print JSON")

    s = sub.add_parser("add", help="append an entry to a ledger file")
    s.add_argument("file", metavar="FILE")
    s.add_argument("date", metavar="DATE")
    s.add_argument("category", metavar="CATEGORY")
    s.add_argument("amount", metavar="AMOUNT")
    s.add_argument("note", metavar="NOTE", nargs="?", default="")

    s = sub.add_parser("export", help="export entries")
    s.add_argument("file", metavar="FILE")
    s.add_argument("--format", choices=["csv"], default="csv")
    return p


class _ReadError(Exception):
    pass


def _read_ledger_text(path):
    try:
        if path == "-":
            buf = getattr(sys.stdin, "buffer", None)
            if buf is not None:
                return buf.read().decode("utf-8")
            return sys.stdin.read()
        with open(path, "rb") as f:
            return f.read().decode("utf-8")
    except (OSError, UnicodeDecodeError) as exc:
        raise _ReadError("cannot read %s: %s" % (path, exc)) from None


def _load(path):
    return ledger.parse(_read_ledger_text(path))


def _sorted_entries(entries):
    return sorted(entries, key=lambda e: e.date)  # stable


def _entry_dict(e):
    return {
        "date": e.date.isoformat(),
        "category": e.category,
        "amount": ledger.format_money(e.amount),
        "note": e.note,
    }


def _cmd_balance(args):
    total = ledger.format_money(ledger.balance(_load(args.file)))
    return json.dumps({"balance": total}) + "\n" if args.json else total + "\n"


def _cmd_summary(args):
    entries = _load(args.file)
    totals = (
        ledger.by_month(entries) if args.by == "month" else ledger.by_category(entries)
    )
    rows = [(k, ledger.format_money(totals[k])) for k in sorted(totals)]
    if args.json:
        return json.dumps(dict(rows)) + "\n"
    return "".join("%s  %s\n" % row for row in rows)


def _cmd_list(args):
    entries = ledger.filter_entries(
        _load(args.file), args.category, args.since, args.until
    )
    entries = _sorted_entries(entries)
    if args.json:
        return json.dumps([_entry_dict(e) for e in entries]) + "\n"
    return "".join(ledger.format_entry(e) + "\n" for e in entries)


def _cmd_export(args):
    entries = _sorted_entries(_load(args.file))
    out = io.StringIO()
    w = csv.writer(out, lineterminator="\n")
    w.writerow(["date", "category", "amount", "note"])
    for e in entries:
        d = _entry_dict(e)
        w.writerow([d["date"], d["category"], d["amount"], d["note"]])
    return out.getvalue()


def _cmd_add(args):
    try:
        with open(args.file, "rb") as f:
            existing = f.read()
    except FileNotFoundError:
        existing = b""
    except OSError as exc:
        raise _ReadError("cannot read %s: %s" % (args.file, exc)) from None
    lineno = len(existing.decode("utf-8", "replace").splitlines()) + 1

    for name, value in (
        ("date", args.date),
        ("category", args.category),
        ("amount", args.amount),
    ):
        if value == "" or re.search(r"[ \t\r\n]", value):
            raise ParseError(lineno, "%s must be a single non-empty word" % name)
    line = "%s %s %s" % (args.date, args.category, args.amount)
    if args.note.strip():
        line += " " + args.note
    if len(line.splitlines()) != 1:
        raise ParseError(lineno, "entry must be a single line")
    entry = ledger.parse_line(line, lineno)

    prefix = b"" if not existing or existing.endswith((b"\n", b"\r")) else b"\n"
    try:
        with open(args.file, "ab") as f:
            f.write(prefix + (line + "\n").encode("utf-8"))
    except OSError as exc:
        raise _ReadError("cannot write %s: %s" % (args.file, exc)) from None
    return ledger.format_entry(entry) + "\n"


_COMMANDS = {
    "balance": _cmd_balance,
    "summary": _cmd_summary,
    "list": _cmd_list,
    "add": _cmd_add,
    "export": _cmd_export,
}


def main(argv=None):
    parser = _build_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:
        return exc.code if isinstance(exc.code, int) else 2
    if args.command is None:
        parser.print_usage(sys.stderr)
        return 2
    try:
        out = _COMMANDS[args.command](args)
    except ParseError as exc:
        print("pennywise: %s" % exc, file=sys.stderr)
        return 1
    except _ReadError as exc:
        print("pennywise: %s" % exc, file=sys.stderr)
        return 2
    sys.stdout.write(out)
    return 0
"""Ledger parsing, aggregation and formatting."""

import re
from dataclasses import dataclass
from datetime import date
from decimal import Decimal

_DATE_RE = re.compile(r"\d{4}-\d{2}-\d{2}", re.ASCII)
_AMOUNT_RE = re.compile(r"[+-]?\d+(\.\d{1,2})?", re.ASCII)
_TWO = Decimal("0.01")


class ParseError(ValueError):
    """A bad ledger line. ``line`` is the 1-based line number."""

    def __init__(self, line, reason):
        self.line = line
        self.reason = reason
        super().__init__("line %d: %s" % (line, reason))


@dataclass(frozen=True)
class Entry:
    date: date
    category: str
    amount: Decimal
    note: str = ""


_LINE_RE = re.compile(r"^[ \t]*([^ \t]+)[ \t]+([^ \t]+)[ \t]+([^ \t]+)(?:[ \t]+(.*))?$", re.ASCII)


def parse_line(text, lineno):
    """Parse one non-blank, non-comment line into an Entry."""
    m = _LINE_RE.match(text)
    if m is None:
        raise ParseError(lineno, "expected DATE CATEGORY AMOUNT [NOTE]")
    d, cat, amt, note = m.group(1), m.group(2), m.group(3), m.group(4) or ""
    if not _DATE_RE.fullmatch(d):
        raise ParseError(lineno, "bad date %r (expected YYYY-MM-DD)" % d)
    try:
        when = date(int(d[:4]), int(d[5:7]), int(d[8:10]))
    except ValueError:
        raise ParseError(lineno, "invalid date %r" % d) from None
    if not _AMOUNT_RE.fullmatch(amt):
        raise ParseError(lineno, "bad amount %r" % amt)
    return Entry(when, cat.lower(), Decimal(amt), note.strip())


def parse(text):
    """Parse ledger text into a list of Entry, in file order."""
    entries = []
    for n, raw in enumerate(text.splitlines(), 1):
        stripped = raw.strip()
        if stripped == "" or stripped.startswith("#"):
            continue
        entries.append(parse_line(raw, n))
    return entries


def balance(entries):
    return sum((e.amount for e in entries), Decimal("0"))


def by_category(entries):
    out = {}
    for e in entries:
        out[e.category] = out.get(e.category, Decimal("0")) + e.amount
    return out


def by_month(entries):
    out = {}
    for e in entries:
        key = "%04d-%02d" % (e.date.year, e.date.month)
        out[key] = out.get(key, Decimal("0")) + e.amount
    return out


def filter_entries(entries, category=None, since=None, until=None):
    cat = category.lower() if category is not None else None
    out = []
    for e in entries:
        if cat is not None and e.category != cat:
            continue
        if since is not None and e.date < since:
            continue
        if until is not None and e.date > until:
            continue
        out.append(e)
    return out


def format_money(value):
    """Amount with 2 decimals, no '+' sign, no negative zero."""
    q = Decimal(value).quantize(_TWO)
    if q == 0:
        q = abs(q)
    return "{:f}".format(q)


def format_entry(e):
    line = "%s %s %s" % (e.date.isoformat(), e.category, format_money(e.amount))
    if e.note:
        line += " " + e.note
    return line
